#!/usr/bin/env node
/**
 * Merges BLUEPRINT-ITEMS.json (the blueprint's own 1610 items, regenerated by
 * extract-blueprint-checklist.mjs) with TRACKING.json (hand-recorded evidence: commit SHA +
 * either a passing test name or a file:line a human/agent can open and check) into
 * TRACKING-CHECKLIST.md.
 *
 * The rule this enforces: an item is only ever marked done here if TRACKING.json has a
 * {commit, proof} entry for its id. Nothing here infers completion from keyword matching —
 * that produces false positives. A checked box always has a receipt next to it.
 */
import { readFileSync, writeFileSync } from 'node:fs';

const items = JSON.parse(readFileSync(new URL('../docs/v6-blueprint/BLUEPRINT-ITEMS.json', import.meta.url), 'utf8')).items;
const tracking = JSON.parse(readFileSync(new URL('../docs/v6-blueprint/TRACKING.json', import.meta.url), 'utf8')).evidence;

const bySection = new Map();
for (const it of items) {
  if (!bySection.has(it.section)) bySection.set(it.section, []);
  bySection.get(it.section).push(it);
}

let done = 0;
const lines = [];
lines.push('# UAP v6 blueprint — tracking checklist (generated, do not hand-edit)');
lines.push('');
lines.push('Generated by `node scripts/merge-tracking.mjs`. Source of truth for status is');
lines.push('`docs/v6-blueprint/TRACKING.json` (evidence: commit + file + optional test string per');
lines.push('item id) — edit THAT file and regenerate, never tick a box directly in this file.');
lines.push('');
lines.push('A box is checked only when TRACKING.json has a real entry for its id AND');
lines.push('`node scripts/verify-tracking.mjs` confirms the cited file exists and (if given) the');
lines.push('cited test string is actually present in it. No keyword matching against the');
lines.push('blueprint text, no inference, no self-grading without a citation that was verified.');
lines.push('');
lines.push('<!-- TOTAL_PLACEHOLDER -->');
lines.push('');

for (const [section, list] of bySection) {
  const sectionDone = list.filter((it) => tracking[it.id]).length;
  lines.push(`## ${section} (${sectionDone}/${list.length})`);
  lines.push('');
  for (const it of list) {
    const ev = tracking[it.id];
    if (ev) {
      done += 1;
      lines.push(`- [x] **${it.id}** ${it.text} — _${ev.commit} ${ev.file}${ev.test ? ` (\`${ev.test}\`)` : ''}: ${ev.note}_`);
    } else {
      lines.push(`- [ ] **${it.id}** ${it.text}`);
    }
  }
  lines.push('');
}

const header = `**${done} / ${items.length} checked, each with a cited commit + test/file.**`;
const out = lines.join('\n').replace('<!-- TOTAL_PLACEHOLDER -->', header);
writeFileSync(new URL('../docs/v6-blueprint/TRACKING-CHECKLIST.md', import.meta.url), out + '\n');
console.log(`${done} / ${items.length} items have cited evidence.`);
